custom_defined_behaviors:
// ERGO-LR layout (based on AZERTY-fr-FR) behaviors for ZMK firmware

// Punctuation morphing
behaviors {
  // Key Comma (,) / Semi-colon (;)
  comma_semicolon: comma_semicolon {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp M>, <&kp COMMA>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key Dot (.) / Colon (:)
  dot_colon: dot_colon {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp LS(COMMA)>, <&kp DOT>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key Minus (-) / Underscore (_)
  minus_under: minus_under {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp N6>, <&kp N8>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key Question mark (?) / Exclamation mark (!)
  qmark_excl: qmark_excl {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp LS(M)>, <&kp SLASH>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
};

// Number morphing
behaviors {
  // Key 1 / Dollar (Right Bracket position in QWERTY)
  n1_dollar: n1_dollar {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp RBKT>, <&kp LS(N1)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 2 / Euro
  n2_euro: n2_euro {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp RA(E)>, <&kp LS(N2)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 5 / Percent
  n5_percent: n5_percent {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp LS(APOS)>, <&kp LS(N5)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 6 / Left parenthesis
  n6_left_parenthesis: n6_left_parenthesis {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp N5>, <&kp LS(N6)>; // Normal (N5 = () / Shifted (ZMK relâche Shift, envoie LS(N6) = 6)
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 7 / Right parenthesis
  n7_right_parenthesis: n7_right_parenthesis {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp MINUS>, <&kp LS(N7)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 8 / At sign '@' (Arobase)
  n8_at: n8_at {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp RA(N0)>, <&kp LS(N8)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 9 / Hash
  n9_hash: n9_hash {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp RA(N3)>, <&kp LS(N9)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };

  // Key 0 / Slash
  n0_slash: n0_slash {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp LS(DOT)>, <&kp LS(N0)>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
};
